import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { useState } from "react";
import { Input } from "@/registry/erbium/ui/input";
import { useCopyToClipboard } from "@/registry/erbium/hooks/use-copy-to-clipboard";

const feedback = {
  copied: "URL copied.",
  error: "Could not copy the URL.",
  idle: "Press Enter to copy the URL.",
};

export default function UseCopyToClipboardExample() {
  const [value, setValue] = useState("https://ui.erbium.app");
  const { copyToClipboard, reset, revision, status } = useCopyToClipboard();

  return (
    <form
      className="grid w-80 max-w-full gap-related"
      onSubmit={(event) => {
        event.preventDefault();
        void copyToClipboard(value);
      }}
    >
      <Input
        aria-label="URL"
        enterKeyHint="go"
        value={value}
        onChange={(event) => {
          setValue(event.target.value);
          reset();
        }}
      />
      <output aria-atomic="true" className="min-h-5 text-caption">
        <span key={revision}>{feedback[status]}</span>
      </output>
    </form>
  );
}

