  const { copyToClipboard, reset, revision, status } = useCopyToClipboard();

  return (
    <form
      className="grid w-80 max-w-full gap-related"
      onSubmit={(event) => {
        event.preventDefault();
        void copyToClipboard(value);
      }}
    >
      <Input
        aria-label="URL"
        enterKeyHint="go"
        value={value}
        onChange={(event) => {
          setValue(event.target.value);
