}
" },
    },
  },
  render: OverviewExample,
};

export const CustomButton: Story = {
  parameters: {
    docs: {
      description: { story: "Render CopyButton as an embedded InputGroupButton for a read-only field. Its icon and label share clipboard state and announce the result." },
      source: { code: "import { CopyButton, CopyButtonIcon, CopyButtonLabel } from "@/registry/erbium/blocks/copy-button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/registry/erbium/ui/input-group";

const url = "https://ui.erbium.app";

export default function UseCopyToClipboardCustomButtonExample() {
  return (
    <InputGroup className="w-80">
      <InputGroupInput aria-label="Project URL" readOnly value={url} />
      <InputGroupAddon align="inline-end">
        <CopyButton
          aria-label="Copy project URL"
          render={<InputGroupButton variant="embedded" size="xs" />}
          value={url}
        >
          <CopyButtonIcon data-icon="inline-start" />
          <CopyButtonLabel />
        </CopyButton>
      </InputGroupAddon>
    </InputGroup>
  );
}
" },
    },
  },
  render: CustomButtonExample,
};

